import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Download, ShieldCheck, Smartphone, MapPin, BadgeCheck, Zap, Loader2 } from 'lucide-react';
import html2canvas from 'html2canvas';
import { PROFILE_IMAGE } from '../constants';

interface DigitalIDProps {
  isOpen: boolean;
  onClose: () => void;
}

const DigitalID: React.FC<DigitalIDProps> = ({ isOpen, onClose }) => {
  const cardRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [scale, setScale] = useState(1);
  const [isExporting, setIsExporting] = useState(false);

  useEffect(() => {
    const handleResize = () => {
      const width = window.innerWidth;
      if (width < 500) {
        const newScale = Math.min((width - 32) / 480, 1);
        setScale(newScale);
      } else {
        setScale(1);
      }
    };

    if (isOpen) {
      handleResize();
      window.addEventListener('resize', handleResize);
    }
    return () => window.removeEventListener('resize', handleResize);
  }, [isOpen]);

  const downloadID = async () => {
    if (!cardRef.current || isExporting) return;

    setIsExporting(true);

    try {
      await new Promise(resolve => setTimeout(resolve, 100));

      const canvas = await html2canvas(cardRef.current, {
        scale: 3,
        backgroundColor: null,
        useCORS: true,
        logging: false,
        onclone: (clonedDoc) => {
          const clonedCard = clonedDoc.querySelector('[data-id-card="true"]') as HTMLElement;
          if (clonedCard) {
            clonedCard.style.transform = "none";
            clonedCard.style.position = "relative";
            clonedCard.style.left = "0";
            clonedCard.style.top = "0";
            clonedCard.style.width = "480px";
            clonedCard.style.height = "300px";
            clonedCard.style.margin = "0";
            clonedCard.style.display = "block";

            const texts = clonedCard.querySelectorAll('p, span, h1, h2');
            texts.forEach((el: any) => {
              el.style.fontSmoothing = "antialiased";
              el.style.textRendering = "optimizeLegibility";
            });
          }
        }
      });

      const imageUrl = canvas.toDataURL('image/png', 1.0);
      const link = document.createElement('a');
      link.download = `Arnob_Web_ID_Verified.png`;
      link.href = imageUrl;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    } catch (error) {
      console.error("Failed to export ID Card:", error);
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[1100] flex items-center justify-center p-4">
          <motion.div 
            initial={{ opacity: 0 }} 
            animate={{ opacity: 1 }} 
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="absolute inset-0 bg-slate-950/95 backdrop-blur-xl" 
          />

          <motion.div
            ref={containerRef}
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.8 }}
            className="relative w-full max-w-lg flex flex-col items-center"
          >
            <div className="flex justify-between w-full mb-6 items-center px-4 max-w-[480px]">
              <span className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-500 flex items-center gap-2">
                <ShieldCheck size={16} /> Verified Identity
              </span>
              <button 
                onClick={onClose} 
                className="p-2 hover:bg-white/10 rounded-full text-white transition-colors cursor-pointer"
              >
                <X size={20} />
              </button>
            </div>

            {/* The ID Card Display */}
            <div 
              style={{ transform: `scale(${scale})`, transformOrigin: 'center center' }}
              className="w-full flex justify-center"
            >
              <div 
                ref={cardRef} 
                data-id-card="true"
                className="relative w-[480px] h-[300px] bg-[#0f172a] rounded-[2.5rem] border border-white/20 shadow-2xl overflow-hidden p-8 flex flex-col justify-between shrink-0"
              >
                {/* Background Decor */}
                <div className="absolute top-0 right-0 w-64 h-64 bg-blue-600/20 blur-[100px] -mr-32 -mt-32 pointer-events-none" />
                <div className="absolute bottom-0 left-0 w-64 h-64 bg-indigo-600/10 blur-[100px] -ml-32 -mb-32 pointer-events-none" />

                <div className="flex justify-between items-start relative z-10">
                  <div className="flex flex-col">
                    <h1 className="text-3xl font-black text-white tracking-tighter leading-none mb-1">
                      ARNOB<span className="text-blue-500">.</span>
                    </h1>
                    <span className="text-[8px] font-black uppercase text-slate-500 tracking-[0.3em]">REF: PPI-ARCH-2026-X</span>
                  </div>
                  <div className="p-2 bg-blue-500/10 border border-blue-500/20 rounded-xl">
                    <BadgeCheck size={28} className="text-blue-500" />
                  </div>
                </div>

                <div className="flex gap-6 relative z-10 items-center">
                  <div className="relative shrink-0">
                    <div className="w-24 h-24 rounded-2xl overflow-hidden border-2 border-blue-500/30 shadow-2xl bg-slate-800">
                      <img 
                        crossOrigin="anonymous"
                        src={PROFILE_IMAGE} 
                        alt="Profile" 
                        className="w-full h-full object-cover" 
                      />
                    </div>
                    <div className="absolute -bottom-1 -right-1 p-2 bg-blue-600 rounded-lg text-white shadow-lg border border-white/20">
                      <Zap size={14} fill="currentColor" />
                    </div>
                  </div>

                  <div className="flex-1 space-y-2 overflow-hidden">
                    <h2 
                      className="text-3xl font-black text-white tracking-tight truncate leading-tight"
                    >
                      Arnob Mahmud
                    </h2>
                    <div className="space-y-1.5 text-slate-300 text-[11px]">
                      <p className="flex items-center gap-2 font-black tracking-widest uppercase opacity-80">
                        <Smartphone size={12} className="text-blue-500 shrink-0" /> +880 1319 156 975
                      </p>
                      <p className="flex items-center gap-2 font-black tracking-widest uppercase opacity-80">
                        <MapPin size={12} className="text-blue-500 shrink-0" /> Pabna, Bangladesh
                      </p>
                    </div>
                  </div>

                  <div className="shrink-0 bg-white p-2 rounded-xl shadow-2xl border border-white/20">
                    <img 
                      crossOrigin="anonymous"
                      src="https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=https://arnob-mahmud.netlify.app" 
                      className="w-16 h-16" 
                      alt="Identity QR" 
                    />
                  </div>
                </div>

                {/* Security watermark footer */}
                <div className="relative z-10 flex justify-center opacity-30">
                  <span className="text-[7px] font-black uppercase tracking-[0.6em] text-slate-400">OFFICIAL WEB PASSPORT • 2026 EDITION</span>
                </div>
              </div>
            </div>

            <div className="flex flex-col sm:flex-row gap-4 mt-8 w-full max-w-sm px-4">
              <motion.button 
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                disabled={isExporting}
                onClick={downloadID} 
                className={`flex-1 py-4 rounded-2xl font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2 shadow-2xl transition-all ${
                  isExporting ? 'bg-blue-800 opacity-80' : 'bg-blue-600 hover:bg-blue-700 text-white shadow-blue-500/40'
                }`}
              >
                {isExporting ? (
                  <>
                    <Loader2 size={18} className="animate-spin" />
                    <span>Saving...</span>
                  </>
                ) : (
                  <>
                    <Download size={18} />
                    <span>Save Image</span>
                  </>
                )}
              </motion.button>
              <button 
                onClick={onClose}
                className="px-8 py-4 glass border border-white/10 text-white rounded-2xl font-black text-xs uppercase tracking-widest cursor-pointer hover:bg-white/10"
              >
                Cancel
              </button>
            </div>
          </motion.div>
        </div>
      )}
